// 校验必填字段
const REQUIRED_FIELDS = ['requestId', 'estimatedAmount', 'employeeEmail', 'employeeName', 'destination', 'costCenter', 'managerEmail'];

const body = $json.body || {};
const missingFields = REQUIRED_FIELDS.filter(f => !body[f]);

if (missingFields.length > 0) {
  throw new Error(`缺少必填字段: ${missingFields.join(', ')}`);
}

if (typeof body.estimatedAmount !== 'number' || body.estimatedAmount <= 0) {
  throw new Error('estimatedAmount 必须是正数');
}

return [{ json: body }];

// 审批金额阈值配置（ALL_CAPS）
const APPROVAL_THRESHOLDS = {
  AUTO_APPROVE_LIMIT: 1000,       // ≤ 此金额（元）自动审批
  SINGLE_APPROVER_LIMIT: 10000    // ≤ 此金额单级审批，> 此金额三级审批
};

// 测试占位符审批人配置 — 生产环境请替换为真实邮箱
const MOCK_APPROVERS = {
  LEVEL_1_MANAGER: 'manager@test.example.com',
  LEVEL_2_DEPT_MANAGER: 'deptmgr@test.example.com',
  LEVEL_3_FINANCE: 'finance@test.example.com'
};

const requestData = $('Travel Request Submitted').item.json.body;
const amount = requestData.estimatedAmount;

let routeType;
if (amount <= APPROVAL_THRESHOLDS.AUTO_APPROVE_LIMIT) {
  routeType = 'auto_approve';
} else if (amount <= APPROVAL_THRESHOLDS.SINGLE_APPROVER_LIMIT) {
  routeType = 'single_approval';
} else {
  routeType = 'multi_approval';
}

return [{
  json: {
    ...requestData,
    routeType,
    approvers: MOCK_APPROVERS,
    thresholds: APPROVAL_THRESHOLDS
  }
}];

